-- Row convention checks (plan 14.2): legacy_source, on every table that carries the pair.
ALTER TABLE "school_packages" ADD CONSTRAINT "ck_school_packages_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "school_subscriptions" ADD CONSTRAINT "ck_school_subscriptions_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "parent_links" ADD CONSTRAINT "ck_parent_links_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "parent_invites" ADD CONSTRAINT "ck_parent_invites_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "comp_students" ADD CONSTRAINT "ck_comp_students_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));

-- Enums as text + check (English codes of @pp/contract: SCHOOL_FORM_LEVELS, SUBSCRIPTION_STATUSES, SUBSCRIPTION_TIERS).
ALTER TABLE "school_packages" ADD CONSTRAINT "ck_school_packages_code" CHECK ("code" IN ('T4', 'T5', 'D1_D6', 'T1_T3'));
ALTER TABLE "school_packages" ADD CONSTRAINT "ck_school_packages_education_level" CHECK ("education_level" IN ('spm', 'primary', 'lower_secondary'));
ALTER TABLE "school_packages" ADD CONSTRAINT "ck_school_packages_form_level" CHECK ("form_level" IN ('t4', 't5', 'd1_d6', 't1_t3'));
ALTER TABLE "school_packages" ADD CONSTRAINT "ck_school_packages_price_annual" CHECK ("price_annual" >= 0);
ALTER TABLE "school_packages" ADD CONSTRAINT "ck_school_packages_max_renewals" CHECK ("max_renewals" >= 0);

ALTER TABLE "school_subscriptions" ADD CONSTRAINT "ck_school_subscriptions_package_tier" CHECK ("package_tier" IN ('basic', 'full'));
ALTER TABLE "school_subscriptions" ADD CONSTRAINT "ck_school_subscriptions_status" CHECK ("status" IN ('active', 'grace', 'expired', 'cancelled'));
ALTER TABLE "school_subscriptions" ADD CONSTRAINT "ck_school_subscriptions_student_quota" CHECK ("student_quota" IS NULL OR "student_quota" >= 1);
ALTER TABLE "school_subscriptions" ADD CONSTRAINT "ck_school_subscriptions_question_limit" CHECK ("question_limit" IS NULL OR "question_limit" >= 1);
ALTER TABLE "school_subscriptions" ADD CONSTRAINT "ck_school_subscriptions_dates" CHECK ("ends_on" >= "starts_on");

ALTER TABLE "user_packages" ADD CONSTRAINT "ck_user_packages_form_level" CHECK ("form_level" IN ('t4', 't5'));
ALTER TABLE "user_packages" ADD CONSTRAINT "ck_user_packages_student_quota" CHECK ("student_quota" >= 1);

-- A parent is never their own child; relationship is free text of at most 50 characters (contract PARENT_RELATIONSHIP_MAX).
ALTER TABLE "parent_links" ADD CONSTRAINT "ck_parent_links_not_self" CHECK ("parent_id" <> "student_id");
ALTER TABLE "parent_links" ADD CONSTRAINT "ck_parent_links_relationship" CHECK ("relationship" IS NULL OR char_length("relationship") BETWEEN 1 AND 50);

-- The stored token value is a hash (hex digest), never a raw token: at least 32 characters.
ALTER TABLE "parent_invites" ADD CONSTRAINT "ck_parent_invites_token_hash" CHECK (char_length("token_hash") >= 32);
-- Single use: a used invite records who accepted it only together with used_at.
ALTER TABLE "parent_invites" ADD CONSTRAINT "ck_parent_invites_accepted" CHECK ("accepted_by_id" IS NULL OR "used_at" IS NOT NULL);
